import { useState, useEffect, useRef, useCallback } from 'react'
import useFootage from '../../../hooks/useFootage'
import useCaptions from '../../../hooks/useCaptions'
import { concatenateVideos } from '../../../utilities/videoEditor'
import LoadingSpinner from '../../../components/LoadingSpinner/LoadingSpinner'
import styles from './Video.module.css'

function Video({ videoRef }) {
  const { footage } = useFootage()
  const { captions } = useCaptions()
  const [source, setSource] = useState('')
  const [activeCaption, setActiveCaption] = useState({})
  const [progress, setProgress] = useState(0)
  const [loading, setLoading] = useState(false)
  const activeCaptionRef = useRef(activeCaption)

  const onTimeUpdate = useCallback(() => {
    const { currentTime } = videoRef.current
    const currentActive = activeCaptionRef.current
    const matchingCaption = captions.find(caption => {
      return currentTime >= Number(caption.start) && currentTime <= Number(caption.end)
    })
    if (matchingCaption && matchingCaption.id !== currentActive?.id) {
      return setActiveCaption(matchingCaption)
    } 
    if (!matchingCaption && currentActive?.id !== undefined) {
      return setActiveCaption({})
    }
  }, [videoRef, captions])

  useEffect(() => {
    activeCaptionRef.current = activeCaption
  }, [activeCaption])
  
  useEffect(() => {
    let unmounted = false
    let activeUrl = ''
  
    const init = async () => {
      try {
        setLoading(true)
        const blob = await concatenateVideos(footage, setProgress)
        // Short-circuit instantly if the user navigated away while compiling
        if (unmounted) {
          return 
        }
        const url = URL.createObjectURL(blob)
        activeUrl = url
        setSource(url)
      } catch (error) {
        alert('Video export failed.')
        console.error('Error concatenating video clips.', error)
      } finally {
        if (!unmounted) {
          setLoading(false)
        }
      }
    }
  
    init()
  
    return () => {
      unmounted = true
      if (activeUrl) {
        URL.revokeObjectURL(activeUrl)
      }
    }
  }, [footage])

  useEffect(() => {
    const video = videoRef.current
    if (!video) {
      return
    }
    video.addEventListener('timeupdate', onTimeUpdate)
    return () => {
      video.removeEventListener('timeupdate', onTimeUpdate)
    }
  }, [videoRef, onTimeUpdate])
  
  return loading ? <LoadingSpinner /> : (
    <figure className={styles.Video}>
      <video id="video-editor" ref={videoRef} src={source} autoPlay playsInline 
        onLoadedMetadata={() => console.log('Video metadata loaded')}
        onCanPlay={() => console.log('Video can play')}
        onError={e => console.error('Video error:', e.currentTarget.error)}
      />
      {activeCaption?.text && <figcaption style={activeCaption.style}>{activeCaption.text}</figcaption>}
    </figure>
  )
}

export default Video
